RED.liveSync = (function() {

    var active = false;
    var _isRemoteApply = false;
    var _changeCounter = 0;
    var _pendingChanges = {}; // changeId -> {changes, timestamp}
    var _status = 'disconnected'; // 'live', 'applying', 'error', 'disconnected'

    function init() {
        active = true;
        _status = 'live';

        // Subscribe to livesync messages from server
        RED.comms.subscribe("livesync/#", function(topic, data) {
            if (topic === "livesync/applied") {
                handleApplied(data);
            } else if (topic === "livesync/error") {
                handleError(data);
            }
        });

        // Listen for comms connection state
        RED.events.on("comms:connected", function() {
            _status = 'live';
            RED.events.emit("livesync:status-changed", { status: _status });
        });
        RED.events.on("comms:disconnected", function() {
            _status = 'disconnected';
            RED.events.emit("livesync:status-changed", { status: _status });
        });

        RED.events.emit("livesync:status-changed", { status: _status });
    }

    function isActive() {
        return active;
    }

    function getStatus() {
        return _status;
    }

    /**
     * Translate a history event into change operations and send to server.
     * Called from RED.history.push() when live sync is active.
     */
    function publishChange(ev) {
        if (_isRemoteApply) return; // Don't echo remote changes back

        var changes = historyEventToChanges(ev);
        if (changes.length === 0) return;

        var changeId = "chg_" + (++_changeCounter) + "_" + Date.now();

        _pendingChanges[changeId] = {
            changes: changes,
            timestamp: Date.now()
        };

        _status = 'applying';
        RED.events.emit("livesync:status-changed", { status: _status });

        RED.comms.send("livesync/change", {
            changeId: changeId,
            changes: changes
        });
    }

    /**
     * Translate a history event into an array of ChangeOperation objects.
     */
    function historyEventToChanges(ev) {
        var changes = [];

        switch(ev.t) {
            case 'add':
                // Nodes were added
                if (ev.nodes) {
                    ev.nodes.forEach(function(n) {
                        var node = typeof n === 'string' ? RED.nodes.node(n) : n;
                        if (node) {
                            changes.push({ op: 'add', node: cleanNodeForSync(node) });
                        }
                    });
                }
                if (ev.links) {
                    // Links represent wiring changes - extract rewire ops
                    ev.links.forEach(function(link) {
                        var sourceNode = RED.nodes.node(link.source.id);
                        if (sourceNode) {
                            changes.push({
                                op: 'rewire',
                                nodeId: sourceNode.id,
                                wires: sourceNode.wires || []
                            });
                        }
                    });
                }
                if (ev.workspaces) {
                    ev.workspaces.forEach(function(ws) {
                        changes.push({ op: 'add', node: { id: ws.id, type: 'tab', label: ws.label } });
                    });
                }
                if (ev.subflows) {
                    ev.subflows.forEach(function(sf) {
                        changes.push({ op: 'add', node: cleanNodeForSync(sf) });
                    });
                }
                break;

            case 'delete':
                if (ev.nodes) {
                    ev.nodes.forEach(function(n) {
                        var nodeId = typeof n === 'string' ? n : n.id;
                        if (nodeId) {
                            changes.push({ op: 'remove', nodeId: nodeId });
                        }
                    });
                }
                if (ev.workspaces) {
                    ev.workspaces.forEach(function(ws) {
                        changes.push({ op: 'remove', nodeId: ws.id });
                    });
                }
                if (ev.subflows) {
                    ev.subflows.forEach(function(sf) {
                        changes.push({ op: 'remove', nodeId: sf.id });
                    });
                }
                // Also handle link removals as rewire ops
                if (ev.links) {
                    var rewiredSources = {};
                    ev.links.forEach(function(link) {
                        if (!rewiredSources[link.source.id]) {
                            rewiredSources[link.source.id] = true;
                            var sourceNode = RED.nodes.node(link.source.id);
                            if (sourceNode) {
                                changes.push({
                                    op: 'rewire',
                                    nodeId: sourceNode.id,
                                    wires: sourceNode.wires || []
                                });
                            }
                        }
                    });
                }
                break;

            case 'edit':
                if (ev.node && ev.node.id) {
                    var currentNode = RED.nodes.node(ev.node.id) ||
                                     RED.nodes.workspace(ev.node.id) ||
                                     RED.nodes.subflow(ev.node.id);
                    if (currentNode) {
                        changes.push({
                            op: 'update',
                            nodeId: ev.node.id,
                            node: cleanNodeForSync(currentNode)
                        });
                    }
                }
                break;

            case 'move':
                if (ev.nodes) {
                    ev.nodes.forEach(function(nobj) {
                        var n = nobj.n || nobj;
                        changes.push({
                            op: 'update',
                            nodeId: n.id,
                            node: { id: n.id, x: n.x, y: n.y }
                        });
                    });
                }
                break;

            case 'replace':
                // Full replace events send the current state of affected nodes
                if (ev.config) {
                    // This is a complex operation, for now treat as a batch update
                    ev.config.forEach(function(n) {
                        changes.push({
                            op: 'update',
                            nodeId: n.id,
                            node: cleanNodeForSync(n)
                        });
                    });
                }
                break;

            case 'createSubflow':
                if (ev.subflow) {
                    changes.push({ op: 'add', node: cleanNodeForSync(ev.subflow.subflow) });
                    if (ev.subflow.nodes) {
                        ev.subflow.nodes.forEach(function(n) {
                            changes.push({ op: 'add', node: cleanNodeForSync(n) });
                        });
                    }
                }
                break;
        }

        return changes;
    }

    /**
     * Clean a node for transmission - remove internal/editor-only properties.
     */
    function cleanNodeForSync(n) {
        if (!n || typeof n !== 'object') return null;
        var clean = {};
        for (var k in n) {
            if (n.hasOwnProperty(k) &&
                k[0] !== '_' &&
                k !== 'dirty' &&
                k !== 'changed' &&
                k !== 'selected' &&
                k !== 'valid' &&
                k !== 'validationErrors' &&
                typeof n[k] !== 'function') {
                clean[k] = n[k];
            }
        }
        return clean;
    }

    /**
     * Handle livesync/applied message from server.
     */
    function handleApplied(data) {
        // Clean up pending tracking
        if (data.changeId && _pendingChanges[data.changeId]) {
            delete _pendingChanges[data.changeId];
        }

        // Update revision
        if (data.rev) {
            RED.nodes.version(data.rev);
        }

        // Update status
        if (Object.keys(_pendingChanges).length === 0) {
            if (data.results && data.results.failed && data.results.failed.length > 0) {
                _status = 'error';
            } else {
                _status = 'live';
            }
        }
        RED.events.emit("livesync:status-changed", { status: _status });

        // If this change came from another session, apply it locally
        if (data.session && data.session !== (RED.multiplayer && RED.multiplayer.getSessionId ? RED.multiplayer.getSessionId() : null)) {
            applyRemoteChanges(data.changes, data.results);
        }

        // Emit node-level status for failed nodes
        if (data.results && data.results.failed) {
            data.results.failed.forEach(function(f) {
                RED.events.emit("livesync:node-error", { nodeId: f.nodeId, error: f.error });
            });
        }
    }

    /**
     * Handle livesync/error from server.
     */
    function handleError(data) {
        if (data.changeId && _pendingChanges[data.changeId]) {
            delete _pendingChanges[data.changeId];
        }
        _status = 'error';
        RED.events.emit("livesync:status-changed", { status: _status });
        RED.notify(RED._("livesync.error", { error: data.error || "Unknown error" }), "error");
    }

    /**
     * Apply changes from a remote session to the local editor model.
     */
    function applyRemoteChanges(changes, results) {
        if (!changes || !Array.isArray(changes)) return;

        _isRemoteApply = true;
        try {
            changes.forEach(function(change) {
                if (change.op === 'add' && change.node) {
                    applyRemoteAdd(change.node);
                } else if (change.op === 'remove' && change.nodeId) {
                    applyRemoteRemove(change.nodeId);
                } else if (change.op === 'update' && change.nodeId && change.node) {
                    applyRemoteUpdate(change.nodeId, change.node);
                } else if (change.op === 'rewire' && change.nodeId) {
                    applyRemoteRewire(change.nodeId, change.wires);
                }
            });
            RED.view.redraw(true);
        } finally {
            _isRemoteApply = false;
        }
    }

    function applyRemoteAdd(nodeData) {
        if (nodeData.type === 'tab') {
            RED.nodes.addWorkspace(nodeData);
            RED.workspaces.add(nodeData);
        } else if (nodeData.type === 'subflow') {
            RED.nodes.addSubflow(nodeData);
        } else {
            RED.nodes.add(nodeData);
        }
    }

    function applyRemoteRemove(nodeId) {
        var node = RED.nodes.node(nodeId);
        if (node) {
            RED.nodes.remove(nodeId);
            return;
        }
        var ws = RED.nodes.workspace(nodeId);
        if (ws) {
            RED.nodes.removeWorkspace(nodeId);
            RED.workspaces.remove(ws);
            return;
        }
        var sf = RED.nodes.subflow(nodeId);
        if (sf) {
            RED.nodes.removeSubflow(sf);
        }
    }

    function applyRemoteUpdate(nodeId, newProps) {
        var node = RED.nodes.node(nodeId) ||
                   RED.nodes.workspace(nodeId) ||
                   RED.nodes.subflow(nodeId);
        if (!node) return;

        for (var k in newProps) {
            if (newProps.hasOwnProperty(k) && k !== 'id') {
                node[k] = newProps[k];
            }
        }
        node.dirty = true;
    }

    function applyRemoteRewire(nodeId, wires) {
        var node = RED.nodes.node(nodeId);
        if (!node) return;
        node.wires = wires || [];
        node.dirty = true;
    }

    return {
        init: init,
        isActive: isActive,
        getStatus: getStatus,
        publishChange: publishChange,
        historyEventToChanges: historyEventToChanges,
        applyRemoteChanges: applyRemoteChanges
    };

})();
